using System.ComponentModel;
using System.Text.Json;
using ModelContextProtocol.Server;

namespace McpServer;

/// <summary>
/// MCP tool class that wraps a weather REST API.
/// The SDK discovers tools by scanning for [McpServerToolType] on the class
/// and [McpServerTool] on each public method.
/// </summary>
[McpServerToolType]
public sealed class WeatherTools
{
    private readonly HttpClient _httpClient;

    // Constructor injection — the SDK resolves this from the DI container.
    public WeatherTools(HttpClient httpClient)
    {
        _httpClient = httpClient;
    }

    [McpServerTool, Description("Get the current weather forecast for a US location by latitude and longitude.")]
    public async Task<string> GetForecast(
        [Description("Latitude of the location")] double latitude,
        [Description("Longitude of the location")] double longitude,
        CancellationToken cancellationToken = default)
    {
        // weather.gov uses a two-step lookup: points → forecast
        var pointUrl = $"https://api.weather.gov/points/{latitude},{longitude}";
        var pointJson = await _httpClient.GetFromJsonAsync<JsonElement>(pointUrl, cancellationToken);

        var forecastUrl = pointJson.GetProperty("properties").GetProperty("forecast").GetString()
            ?? throw new InvalidOperationException("Forecast URL not found in API response.");

        var forecastJson = await _httpClient.GetFromJsonAsync<JsonElement>(forecastUrl, cancellationToken);
        var periods = forecastJson.GetProperty("properties").GetProperty("periods");

        // Return a concise summary of the first 3 periods.
        var results = periods.EnumerateArray()
            .Take(3)
            .Select(p => $"{p.GetProperty("name")}: {p.GetProperty("detailedForecast")}");

        return string.Join("\n\n", results);
    }

    [McpServerTool, Description("Get active weather alerts for a US state (two-letter code, e.g. 'CA').")]
    public async Task<string> GetAlerts(
        [Description("Two-letter US state code")] string state,
        CancellationToken cancellationToken = default)
    {
        var url = $"https://api.weather.gov/alerts/active/area/{state}";
        var json = await _httpClient.GetFromJsonAsync<JsonElement>(url, cancellationToken);

        var features = json.GetProperty("features");
        if (features.GetArrayLength() == 0)
            return $"No active alerts for {state}.";

        var alerts = features.EnumerateArray()
            .Take(5)
            .Select(f =>
            {
                var props = f.GetProperty("properties");
                return $"[{props.GetProperty("severity")}] {props.GetProperty("headline")}";
            });

        return string.Join("\n", alerts);
    }
}

